- (BOOL)canBecomeFocused
{
  if ([self isTVFocusGuide]) {
    return NO;
  }
  return _props->isTVSelectable;
}

#if TARGET_OS_TV
// Portico: a plain view that cannot take focus itself and either draws no background (an empty, full-screen pass-through
// layer, such as the app's playback host over its pages) or takes no input (pointerEvents none: a dim or a scrim) is
// transparent to the focus engine, so the items under it can still be reached. Without this tvOS treats them as covered and
// offers no move to them at all.
- (BOOL)isTransparentFocusItem
{
  return [self class] == [RCTViewComponentView class] && ![self canBecomeFocused] &&
      (_props->pointerEvents == PointerEventsMode::None || _backgroundColor == nil || CGColorGetAlpha(_backgroundColor.CGColor) == 0);
}
#endif

// Portico: a nextFocus guide sits this far outside its item. Glued to the item's edge it lay inside an item that grows when
// focused (and was further off inside scroll views), so the focus engine never used it.
static const CGFloat kPorticoFocusGuideGap = 40.0;

- (void)enableDirectionalFocusGuides
{
  if (!self.isFocused) {
    return;
  }
  // Portico: resolve the targets each time this item takes focus. They were looked up once, when the prop changed, which for
  // a new view is before it is in the window, so the target stayed nil.
  UIView *porticoRoot = [self containingRootView];
  if (porticoRoot != nil) {
    if (_props->nextFocusUp.has_value()) self->_nextFocusUp = [porticoRoot viewWithTag:_props->nextFocusUp.value()];
    if (_props->nextFocusDown.has_value()) self->_nextFocusDown = [porticoRoot viewWithTag:_props->nextFocusDown.value()];
    if (_props->nextFocusLeft.has_value()) self->_nextFocusLeft = [porticoRoot viewWithTag:_props->nextFocusLeft.value()];
    if (_props->nextFocusRight.has_value()) self->_nextFocusRight = [porticoRoot viewWithTag:_props->nextFocusRight.value()];
  }

if (context.nextFocusedView == self) {
  // Portico: once any view has asked for focus, the root's preferred view follows the view that holds focus, so a
  // dropped focus (tvOS drops it while a large result set mounts under the Search keyboard) goes back to the view
  // last focused, app-wide, not to the view that first asked (the page's entry key, which typed the wrong letter).
  // A view with hasTVPreferredFocus re-asks on layout whenever it is not the preferred view; the kit never sets it.
  RCTSurfaceHostingProxyRootView *porticoRoot = [self containingRootView];
  if (porticoRoot != nil && porticoRoot.reactPreferredFocusedView != nil) {
    porticoRoot.reactPreferredFocusedView = self;
  }
  [self becomeFirstResponder];

// Portico: a view leaving the window stops being the root's preferred view: Fabric recycles component views, and a
// recycled one shown on the next page must never receive a dropped focus meant for the view it used to be. The
// preference falls back to the view JS last asked to focus (the page's entry), while that is still on screen.
- (void)willMoveToWindow:(UIWindow *)newWindow {
  [super willMoveToWindow:newWindow];
  if (newWindow != nil) return;
  RCTSurfaceHostingProxyRootView *porticoRoot = [self containingRootView];
  if (porticoRoot == nil || porticoRoot.reactPreferredFocusedView != self) return;
  UIView *porticoEntry = ((PorticoWeakView *)objc_getAssociatedObject(porticoRoot, &kPorticoFocusEntry)).view;
  BOOL porticoEntryLive = porticoEntry != nil && porticoEntry != self && porticoEntry.window != nil;
  porticoRoot.reactPreferredFocusedView = porticoEntryLive ? porticoEntry : nil;
}

- (void)didMoveToWindow {
  [super didMoveToWindow];

// Portico: the view JS last asked to focus, per root view, held weakly (see willMoveToWindow:).
@interface PorticoWeakView : NSObject
@property (nonatomic, weak) UIView *view;
@end
@implementation PorticoWeakView
@end
static char kPorticoFocusEntry;

@implementation RCTViewComponentView {

rootview.reactPreferredFocusedView = self;
PorticoWeakView *porticoEntry = [PorticoWeakView new];
porticoEntry.view = self;
objc_setAssociatedObject(rootview, &kPorticoFocusEntry, porticoEntry, OBJC_ASSOCIATION_RETAIN_NONATOMIC);

#pragma mark - Apple TV methods

// Portico: a region (a TVFocusGuideView with destinations) named as where focus should go, by a nextFocus guide or by the
// root, hands focus to its destinations, as moving into it by position does. Without this a nextFocus guide aimed at a
// region found nothing focusable in it and tvOS fell back to position (Films › Discover: Up from a card reached the
// library chevron, not the tab; Settings: Right from Switch server went nowhere).
- (NSArray<id<UIFocusEnvironment>> *)preferredFocusEnvironments {
  // Only destinations still on screen inside the region: JS names a new entry one commit after the old one unmounts, and
  // meanwhile Fabric may have recycled that view to show something else.
  if (self.focusGuide != nil) {
    NSMutableArray<id<UIFocusEnvironment>> *porticoLive = [NSMutableArray new];
    for (id destination in _focusDestinations) {
      if ([destination isKindOfClass:UIView.class] && ((UIView *)destination).window != nil && [(UIView *)destination isDescendantOfView:self]) [porticoLive addObject:destination];
    }
    if (porticoLive.count > 0) return porticoLive;
  }
  return [super preferredFocusEnvironments];
}
